    "parameters": {
      "type": "object",
      "properties": {
        "mode": {
          "type": "string",
          "description": "回答模式标识（如 rag_answer / rag_answer_fallback / direct）。"
        },
        "finish_after_tool": {
          "type": "boolean",
          "description": "该工具执行完成后是否可以直接结束本轮请求。若工具结果只是中间状态、后续还要继续规划其它工具，则填 false；若该工具结果就是用户要的最终结果，则填 true。"
        }
      },
      "required": []
    }
  },
  {
    "name": "flux-image-generation",
    "description": "图像生成工具。可纯文本生成，也可结合参考图进行变化生成。",
    "parameters": {
      "type": "object",
      "properties": {
        "task_text": {
          "type": "string"
        },
